export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key) => String(texts[key] || key);
  const esc = (v) => String(v === undefined || v === null ? '' : v)
    .replace(/\\/g, '\\\\')
    .replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');

  // Q32: если сохранение consent_marketing, очистка сессии или чтение события
  // (continueOnFailure на step_3/step_6/step_4) упали — в карточку и в билет
  // уходит один и тот же текст сбоя, а не построенный на неполных данных
  // текст. esc() обязателен — format у step_7/step_8/step_9: MarkdownV2.
  if (inputs.saveConsentError || inputs.clearSessionError || inputs.readEventError) {
    const errText = esc(t('common.err.generic'));
    return { cardText: errText, ticketText: errText, ticketReplyMarkup: {}, now: new Date().toISOString() };
  }

  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const ev = arr(inputs.records).map(flat)[0] || {};
  const isYes = inputs.isYes === true || inputs.isYes === 'true';
  const eventId = String(inputs.eventId === undefined || inputs.eventId === null ? '' : inputs.eventId);
  // ADR-0034: онбординг без диплинка (голый /start) доходит сюда с пустым
  // eventId — регистрации нет, билета нет, финал ведёт в каталог Mini App.
  const hasEvent = eventId !== '';
  const miniappUrl = String(inputs.miniappUrl === undefined || inputs.miniappUrl === null ? '' : inputs.miniappUrl);
  const base = miniappUrl.endsWith('/') ? miniappUrl.slice(0, -1) : miniappUrl;
  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    if (!iso) return '';
    const s = /[Zz]$/.test(iso) || /[+-][0-9]{2}:?[0-9]{2}$/.test(iso) ? iso : iso + 'Z';
    const d = new Date(s);
    return isNaN(d.getTime()) ? '' : dateFmt.format(d);
  };
  // W76: карта в финальной карточке и ссылка «в календарь» в билете.
  const parseIso = (s) => Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  const lat = Number(ev.lat);
  const lon = Number(ev.lon);
  // W76/W72: пустые координаты и (0,0) — не гео (Number('') === 0, баг #124);
  // координаты должны быть в диапазоне.
  const hasGeo = String(ev.lat) !== '' && String(ev.lon) !== '' && isFinite(lat) && isFinite(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180 && !(lat === 0 && lon === 0);
  const mapsUrl = hasGeo ? ('https://yandex.uz/maps/?ll=' + lon + '%2C' + lat + '&z=17&pt=' + lon + '%2C' + lat) : '';
  const utcStamp = (iso) => {
    if (!iso) return '';
    const ms = parseIso(String(iso));
    return isFinite(ms) ? new Date(ms).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '') : '';
  };
  const calUrl = (() => {
    const start = utcStamp(ev.starts_at);
    if (!start) return '';
    let end = utcStamp(ev.ends_at);
    if (!end) {
      const ms = parseIso(String(ev.starts_at));
      end = isFinite(ms) ? new Date(ms + 3600000).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '') : '';
    }
    if (!start || !end) return '';
    const params = ['action=TEMPLATE', 'text=' + encodeURIComponent(String(ev.title || '')), 'dates=' + start + '/' + end];
    if (ev.address) params.push('location=' + encodeURIComponent(String(ev.address)));
    return 'https://calendar.google.com/calendar/render?' + params.join('&');
  })();
  const header = esc(t(hasEvent ? 'reg.done.header' : 'profile.saved.header'));
  const saved = esc(t(isYes ? 'reg.consent_marketing.saved_yes' : 'reg.consent_marketing.saved_no'));
  const cardLines = [header, saved];
  const card = [];
  if (ev.title) card.push('*' + esc(ev.title) + '*');
  if (ev.starts_at) card.push('📅 ' + esc(fmt(ev.starts_at)));
  if (ev.address) card.push('📍 ' + esc(ev.address));
  if (mapsUrl) card.push('🗺 [Открыть на карте](' + mapsUrl + ')');
  if (card.length) cardLines.push(card.join('\n'));

  let ticketText;
  let ticketReplyMarkup;
  if (hasEvent) {
    ticketText = [esc(t('ticket.header')), esc(t('ticket.hint'))].join('\n\n');
    const rows = [[{ text: 'Открыть билет', web_app: { url: base + '/#/ticket?event_id=' + eventId } }]];
    if (calUrl) rows.push([{ text: t('event.card.btn_calendar'), url: calUrl }]);
    ticketReplyMarkup = { inline_keyboard: rows };
  } else {
    ticketText = esc(t('events.catalog.hint'));
    ticketReplyMarkup = { inline_keyboard: [[{ text: t('menu.btn.events'), web_app: { url: base + '/#/events' } }]] };
  }
  return {
    cardText: cardLines.join('\n\n'),
    ticketText: ticketText,
    ticketReplyMarkup: ticketReplyMarkup,
    now: new Date().toISOString()
  };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const isYes = str(inputs.callbackData) === 'reg:mkt:yes';
  let draft = {};
  try { draft = JSON.parse(str(inputs.sessionDraft) || '{}'); } catch (e) { draft = {}; }
  const eventId = str(draft.eventId);
  const utm = str(draft.utm);
  const cardMessageId = Number(draft.cardMessageId);
  const cardId = isFinite(cardMessageId) && cardMessageId > 0 ? cardMessageId : 0;
  return {
    isYes: isYes,
    consentValue: isYes ? 'true' : 'false',
    eventId: eventId, utm: utm, cardMessageId: cardId,
    // Черновик на следующий шаг: promptMessageId допишется после отправки
    // вопроса о телефоне — его message_id до отправки неизвестен.
    draftJson: JSON.stringify({ eventId: eventId, utm: utm, cardMessageId: cardId, promptMessageId: 0 }),
    now: new Date().toISOString()
  };
};
